scwin.grd_List_1_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20600.grd_List_1_OnDblClick" });
