 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20600.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20600.MxDataSet_com_isur_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let secuGrpId = "";
    if (chb_Grp_St.getValue() === 'Y') secuGrpId += '1,';
    if (chb_Grp_Mf.getValue() === 'Y') secuGrpId += '2,';
    if (chb_Grp_Rt.getValue() === 'Y') secuGrpId += '4,';
    if (chb_Grp_Sc.getValue() === 'Y') secuGrpId += '6,';
    if (chb_Grp_All.getValue() === ' Y') secuGrpId = '1,2,4,6';
    let vMarketTpCd = "";
    if (js_market === "1" || js_market === "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = rdo_MARKET_TP_CD.getValue();
    }
    url += "?SCREN_ID=" + "ULDSTF20600.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_CORP_COM_CHG" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.comnm.chane.condition" + "&{P}param01=" + vMarketTpCd + // 시장구분
        "&{P}param02=" + vMarketTpCd + // 시장구분
        "&{P}param03=" + secuGrpId + // 회사구분
        "&{P}param04=" + secuGrpId + // 회사구분
        "&{P}param05=" + rdo_LIST_STAT_CD.getValue() + // 상장구분
        "&{P}param06=" + rdo_LIST_STAT_CD.getValue() + // 상장구분
        "&{P}param07=" + txb_ISUR_CD.getValue() + // 법인코드
        "&{P}param08=" + txb_ISUR_CD.getValue() + // 법인코드
        "&{P}param09=" + edt_SDate.getValue() + // 시작일자
        "&{P}param10=" + edt_EDate.getValue(); // 종료일자
    /*
		var url = "/ListedSearch.do?method=newlistCorporationBook&inputMessageId=LIST_CORPORATIONBOOK_CORPCHG" ;
		url +="&gubun=0" ;
		url +="&LIST_STAT_CD=" + cmd_List4.BindColVal;
		url +="&COM_ATTR_TP_CD=" +secuGrpId;
		url +="&ISUR_CD=" +getObjectValue(txb_IsurCd4);
		url +="&SPOT_ISU_TRD_MKT_TP_CD="  +  rdo_TrdGubun4.codeValue;
        //url +="&YYYYMMDD1=" +getObjectValue(edt_SDate);
        //url +="&YYYYMMDD2=" +getObjectValue(edt_EDate);
     */

    const sbmOptions = {
        id : "sbm_dts_List_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name readDetail
 * @description 그리드 더블클릭시
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readDetail = async function(row, colid) {
    const vIsurCd = dts_List_1.getCellData(row, 'ISUR_CD');
    /*
	    url = "/ListedSearch.do?method=listCorporationBookDtl&inputMessageId=LIST_CORP_COM_CHG" ;
	    url +="&gubun=3" ;
	    url +="&ISUR_CD="   + vIsurCd;
     */
    url += "?SCREN_ID=" + "ULDSTF20600.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_CORP_COM_CHG" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.comnmdtl.chane.condition" + "&{P}param01=" + vIsurCd;
    const sbmOptions = {
        id : "sbm_dts_List_2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    chb_Grp_All.setValue(1);
    scwin.allCheck();

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
};

/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_Grp_St, chb_Grp_Mf, chb_Grp_Sc, chb_Grp_Rt];
    if (chb_Grp_All.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_List_1.getCellData(Number(obj), "ISUR_CD");
};
